CREATE TABLE IF NOT EXISTS projects (id text PRIMARY KEY, name text NOT NULL, description text NOT NULL, website text, repository text, source_url text NOT NULL, revision text NOT NULL, observed_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities (id text PRIMARY KEY, project_a text NOT NULL REFERENCES projects(id), project_b text NOT NULL REFERENCES projects(id), kind text NOT NULL, problem text NOT NULL, reasoning text NOT NULL, requirements text NOT NULL, experiment text NOT NULL, status text NOT NULL);
CREATE TABLE IF NOT EXISTS evidence (id serial PRIMARY KEY, opportunity_id text NOT NULL REFERENCES opportunities(id), claim text NOT NULL, source_url text NOT NULL, revision text, observed_at timestamptz NOT NULL, verification text NOT NULL);
CREATE TABLE IF NOT EXISTS follow_ups (id serial PRIMARY KEY, opportunity_id text NOT NULL REFERENCES opportunities(id), kind text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trial_runs (id serial PRIMARY KEY, opportunity_id text NOT NULL REFERENCES opportunities(id), result text NOT NULL, details text NOT NULL, observed_at timestamptz NOT NULL);
